'use strict';
window.FinanceGroceries=(()=>{
 let db,home,rows=[],ready=false,generation=0,wired=false;
 const $=id=>document.getElementById(id),money=c=>new Intl.NumberFormat('pt-PT',{style:'currency',currency:'EUR'}).format(c/100),date=s=>new Intl.DateTimeFormat('pt-PT',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T12:00:00Z')),today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Lisbon'}).format(new Date());
 const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 function options(){return {month:$('grocery-month').value,retailer:$('grocery-store').value,asOf:today()};}
 function bars(id,entries){const target=$(id);target.replaceChildren();if(!entries.length){target.append(el('p','Sem dados neste filtro.','muted'));return;}const max=Math.max(...entries.map(x=>Math.abs(x[1])),1);for(const [name,value] of entries){const row=el('div',undefined,'bar-row'),label=el('div',undefined,'bar-title');label.append(el('span',name),el('strong',money(value)));const track=el('div',undefined,'bar-track'),fill=el('div',undefined,'bar-fill');fill.style.width=Math.abs(value)/max*100+'%';track.append(fill);row.append(label,track);target.append(row);}}
 async function openSource(source){if(source.upload_id){const u=await db.from('finance_uploads').select('storage_path').eq('household_id',home).eq('id',source.upload_id).single();if(u.error)throw u.error;const r=await db.storage.from('finance-uploads').createSignedUrl(u.data.storage_path,60);if(r.error)throw r.error;window.open(r.data.signedUrl,'_blank','noopener');}else if(source.url){const u=new URL(source.url);if(u.protocol==='https:'&&u.hostname==='drive.google.com')window.open(u.href,'_blank','noopener');}}
 function renderReceipts(data){const target=$('grocery-receipts');target.replaceChildren();for(const r of [...data.scoped].sort((a,b)=>(b.purchased_on||'').localeCompare(a.purchased_on||''))){const detail=el('details',undefined,'panel grocery-receipt'),summary=el('summary',r.store+' · '+(r.purchased_on?date(r.purchased_on):'Sem data')+' · '+(r.total_cents===null?'Por confirmar':money((r.document_kind==='credit'?-1:1)*r.total_cents)));detail.append(summary);detail.append(el('p',r.document_kind==='credit'?'Nota de crédito / devolução':r.card_cents?'Valor da compra: '+money(r.total_cents)+' · Pagamento: '+money(r.paid_cents)+' · Saldo de cartão utilizado: '+money(r.card_cents):'Pagamento documentado: '+(r.paid_cents===null?'Sem valor':money(r.paid_cents)),'small'));if(r.warning)detail.append(el('p',r.warning,'coverage-alert'));const ul=el('ul',undefined,'grocery-item-list');for(const item of r.items)ul.append(el('li',item.name+' · '+item.quantity+' '+item.unit_basis+' · '+money(item.net_cents)+' · '+item.category));detail.append(ul);for(const s of r.sources){const b=el('button',s.upload_id?'Abrir envio na Nesti':'Abrir talão original','text-button');b.type='button';b.onclick=()=>openSource(s).catch(e=>{$('grocery-message').textContent='Não foi possível abrir o documento: '+e.message;});detail.append(b);}target.append(detail);}if(!data.scoped.length)target.append(el('p','Sem talões neste filtro.','muted'));}
 function renderPrices(){const entries=GroceryModel.prices(rows,{...options(),product:$('grocery-product').value}),target=$('grocery-prices');target.replaceChildren();$('grocery-price-note').textContent='';if(!entries.length){target.append(el('p','Sem quantidades e preços unitários comparáveis para este produto e período.','muted'));return;}const basis=[...new Set(entries.map(i=>i.basis))];if(basis.length>1){target.append(el('p','Unidades diferentes neste produto: consulta os preços por unidade na tabela.','coverage-alert'));}for(const p of entries){const tr=el('tr');tr.append(el('td',date(p.date)),el('td',p.store),el('td',money(p.value)+' / '+p.basis),el('td',String(p.quantity)));target.append(tr);}const first=entries[0],last=entries.at(-1);$('grocery-price-note').textContent=entries.length>1&&basis.length===1&&first.value>0?'Variação entre a primeira e a última compra: '+((last.value/first.value-1)*100).toFixed(1)+'%. Reflete os preços pagos, incluindo promoções; não é um índice de inflação.':'Sem duas observações comparáveis para calcular variação.';}
 function render(){if(!ready)return;const data=GroceryModel.summarize(rows,options());$('grocery-total').textContent=data.total===null?'Sem dados':money(data.total);$('grocery-count').textContent=data.purchases;$('grocery-average').textContent=data.average===null?'—':money(data.average);$('grocery-discounts').textContent=money(data.discount);$('grocery-coverage').textContent=data.accepted.length+' documentos com total · '+data.detailed+' com detalhe reconciliado · '+data.withoutDetail+' só com total · '+data.unresolved+' por rever.';
  $('grocery-discount-note').textContent='Descontos informados nos talões; já refletidos nos preços. Saldo do cartão utilizado: '+money(data.card)+'. Carregamentos excluídos do consumo: '+money(data.prepaid)+'.';
  const scopedDates=data.scoped.map(r=>r.purchased_on).filter(Boolean).sort();$('grocery-period-note').textContent=scopedDates.length?'Talões de '+date(scopedDates[0])+' a '+date(scopedDates.at(-1))+'. O arquivo pode não incluir todas as compras.':'Sem talões no período selecionado.';
  bars('grocery-monthly',data.history.map(m=>[m.month,m.value]));bars('grocery-categories',Object.entries(data.categories).sort((a,b)=>b[1]-a[1]));bars('grocery-stores',Object.entries(data.stores).sort((a,b)=>b[1]-a[1]));
  const top=Object.entries(data.categories).sort((a,b)=>b[1]-a[1])[0],food=data.groups['Alimentação e bebidas']||0,other=data.detailTotal-food;
  $('grocery-summary').textContent=data.total===null?'Ainda não há compras verificáveis neste filtro.':(top&&data.detailTotal>0?'A maior categoria é '+top[0]+': '+money(top[1])+' ('+(top[1]/data.detailTotal*100).toFixed(1)+'% dos artigos com detalhe). ':'')+'Alimentação e bebidas: '+money(food)+'; restantes artigos: '+money(other)+'.'+(data.refund?' Devoluções documentadas: '+money(data.refund)+'.':'')+' Para planear cortes, começa pelas categorias com maior peso e revê os produtos recorrentes abaixo. Os meses representam apenas os talões disponíveis e não permitem concluir que o consumo total aumentou ou diminuiu.';
  const q=$('grocery-search').value.toLocaleLowerCase(),lines=data.lines.filter(i=>(i.name+' '+i.category).toLocaleLowerCase().includes(q));$('grocery-item-count').textContent=lines.length+' linhas de artigos; a pesquisa aplica-se só a esta tabela.';const target=$('grocery-items');target.replaceChildren();for(const i of lines.slice(0,250)){const tr=el('tr');tr.append(el('td',date(i.date)),el('td',i.retailer),el('td',i.name),el('td',i.category),el('td',i.quantity+' '+i.unit_basis),el('td',money(i.value)));target.append(tr);}if(lines.length>250)$('grocery-item-count').textContent+=' Mostradas as primeiras 250; afina a pesquisa para ver as restantes.';
  const prev=$('grocery-product').value;const names=[...new Set(data.lines.filter(i=>i.document_kind!=='credit').map(i=>i.name))].sort();$('grocery-product').replaceChildren(...names.map(n=>{const o=el('option',n);o.value=n;return o;}));if(names.includes(prev))$('grocery-product').value=prev;else if(names.length){const counts=new Map();for(const r of rows.filter(r=>r.document_kind!=='credit'&&r.quality==='reconciled'&&r.purchased_on<=today()))for(const i of r.items)counts.set(i.name,(counts.get(i.name)||0)+1);$('grocery-product').value=[...names].sort((a,b)=>(counts.get(b)||0)-(counts.get(a)||0))[0];}renderPrices();renderReceipts(data);
 }
 async function refresh(){const run=++generation,currentHome=home;$('grocery-refresh').disabled=true;$('grocery-message').textContent='A carregar compras…';try{let result=[];for(let offset=0;offset<10000;offset+=200){const q=await db.from('finance_grocery_receipts').select('*').eq('household_id',currentHome).order('id').range(offset,offset+199);if(q.error)throw q.error;result.push(...q.data);if(q.data.length<200)break;if(offset>=9800)throw Error('Arquivo demasiado grande; os totais parciais não serão apresentados.');}if(run!==generation||home!==currentHome)return;rows=result;const previous=$('grocery-month').value,store=$('grocery-store').value,months=[...new Set(rows.filter(r=>r.purchased_on&&r.purchased_on<=today()).map(r=>r.purchased_on.slice(0,7)))].sort().reverse();$('grocery-month').replaceChildren();for(const m of ['all',...months]){const o=el('option',m==='all'?'Todo o arquivo':m);o.value=m;$('grocery-month').append(o);}$('grocery-month').value=['all',...months].includes(previous)?previous:'all';$('grocery-store').replaceChildren();for(const s of ['all',...[...new Set(rows.map(r=>r.retailer))].sort()]){const o=el('option',s==='all'?'Todas as lojas':s);o.value=s;$('grocery-store').append(o);}$('grocery-store').value=[...$('grocery-store').options].some(o=>o.value===store)?store:'all';ready=true;$('grocery-message').textContent='';render();}catch(e){if(run!==generation)return;reset(false);$('grocery-message').textContent='Não foi possível carregar as compras. '+e.message;}finally{if(run===generation)$('grocery-refresh').disabled=false;}}
 function reset(clearHome=true){generation++;ready=false;rows=[];if(clearHome)home=null;for(const id of ['grocery-total','grocery-count','grocery-average','grocery-discounts'])$(id).textContent='—';for(const id of ['grocery-monthly','grocery-categories','grocery-stores','grocery-items','grocery-receipts','grocery-prices'])$(id).replaceChildren();for(const id of ['grocery-summary','grocery-coverage','grocery-period-note','grocery-item-count','grocery-price-note','grocery-discount-note'])$(id).textContent='';$('grocery-refresh').disabled=false;}
 function download(){if(!ready)return;const d=GroceryModel.summarize(rows,options()),quote=s=>'"'+String(s??'').replace(/"/g,'""')+'"',csv=[['Data','Loja','Produto','Categoria','Quantidade','Unidade','Valor EUR'],...d.lines.map(i=>[i.date,i.retailer,i.name,i.category,i.quantity,i.unit_basis,(i.value/100).toFixed(2)])].map(r=>r.map(quote).join(';')).join('\r\n'),url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'})),a=el('a');a.href=url;a.download='nesti-compras.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 return {reset,async start(client,household){db=client;if(!wired){wired=true;$('grocery-refresh').onclick=refresh;$('grocery-month').onchange=$('grocery-store').onchange=render;$('grocery-search').oninput=render;$('grocery-product').onchange=renderPrices;$('grocery-export').onclick=download;}if(home!==household){reset();home=household;}await refresh();}};
})();
